top:
    if (PeekMessageA(&message, 0, 0, 0, PM_REMOVE)) {
        TranslateMessage(&message);
        DispatchMessageA(&message);
        goto top;
    }
    if (IsIconic(g_hwndApp) && !g_videoPaused) {
        do {
            if (GetMessageA(&message, 0, 0, 0)) {
                TranslateMessage(&message);
                DispatchMessageA(&message);
            }
        } while (IsIconic(g_hwndApp) && !g_videoPaused);
        goto top;
    }
    videoNextFrame();
    g_inMessageLoop = 0;
